CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE login_attempts (ip_hash CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, window_start DATETIME NOT NULL);
CREATE TABLE records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, entity VARCHAR(20) NOT NULL, payload JSON NOT NULL, INDEX(entity));
CREATE TABLE bills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payload JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
